update t_material_span_send set del_flag = '1'
where id in

    #{id}

UPDATE T_MATERIAL_SPAN_SEND
SET DEL_FLAG = '1'
WHERE SCHEDULE_DATE = #{scheduleDate}
AND ENTRUST_MIX_AREA = #{mixArea}
AND IS_AUTO = '0'
AND RECEIVE_STATUS = '0'
